"use strict";

// RWF-027's canonical B02, reached through a different route than
// `index.js`: no path here throws at all. BOTH endings return, and both
// returned VALUES are invalid as a class base.
//
//     function twoBad(flag) {
//       if (flag) { return 1; }
//       return 2;
//     }
//     class Mode extends twoBad(FLAG) {}
//
// Every load raises `TypeError: Class extends value 1|2 is not a
// constructor or null`. RWF-022 refuses it because the body is not a single
// unconditional return; the two rules together still see nothing.
const danger = require("./danger");

function dangerousOp(input) {
  return danger.explode(input);
}

function safeOp(input) {
  return "safe:" + input;
}

function twoBad(flag) {
  if (flag) {
    return 1;
  }
  return 2;
}

if (process.env.FIXTURE_LIB_MODE === "fast") {
  module.exports = dangerousOp;
  class Mode extends twoBad(process.env.FIXTURE_LIB_FLAG) {}

  void Mode;
}

module.exports = safeOp;
